REVOKE ALL ON FUNCTION public.record_attempt_v1 FROM PUBLIC, anon, authenticated;$eva_statement_2_18$;
    EXECUTE $eva_statement_2_19$GRANT EXECUTE ON FUNCTION public.record_attempt_v1 TO service_role;$eva_statement_2_19$;
