-- Function: save_session_state_v1 (Optimistic lock + state version check)
CREATE OR REPLACE FUNCTION public.save_session_state_v1(
  p_session_id uuid,
  p_expected_version int,
  p_state jsonb,
  p_active_elapsed_ms bigint,
  p_status text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
